-- Rifts World Book 36: Sovietski - bionic weapons and tools, printed 163-168.
-- 21 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~384-sovietski-bionic-weapons.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- PRINTED 163-168 ARE THE BIONIC WEAPONS AND TOOLS SECTION, from its heading
-- on p.163 to the Weapon to Cyborg Energy Link on p.168; p.169 opens the
-- vehicles chapter. The section holds 30 entries. Two are only pointers
-- (Arrows to the Cyber-Bow, Shoulder Blaster to the Shoulder Turret), which
-- leaves 28 systems; 21 are rows here. The section carries 38 Cost: tokens,
-- most of them per-dose chemical and per-arrow prices kept in cost_note.
--
-- SEVEN REPRINT A HELD ROW WITH THE SAME FIGURES and are left out, the held
-- rows untouched: Electro-Cannon Forearm Blaster, Hydraulic Hammer Hand,
-- Hydraulic Ram Arm, Shoulder Weapon Mounts/Clamps and Weapon to Cyborg
-- Energy Link (all Warlords of Russia), Extendible Hydraulic or Pneumatic
-- Hands/Arm (held as Extendible Hydraulic Hands/Arm) and Grapnel & Launcher
-- (held as LGL-31 Grapnel & Launcher), both Triax and the NGR p.154.
--
-- TWO DIFFER FROM A HELD ROW AND ARE NEW ROWS, the held ones untouched:
-- Quick Draw Holsters (Triax Tech) costs 14,000 where New West p.189 costs
-- 10,000; the Chemical Spray is a 40,000-credit weapon system with a dose
-- payload and a chemical list, where New West p.187 holds an unpriced mining
-- tool. The spray is named Chemical Spray (Sovietski) so the two can be told
-- apart in a picker.
--
-- A cost printed as two figures (grenade launcher by mount, clawed feet by
-- claw type, large drum plain or divided, tentacles one or a pair) stores the
-- lower, with both in cost_note. The Cyber-Bow prices only its arrows and
-- the Net Launcher prints no price: both store no cost. The Projectile
-- Weapons blaster's Penalties, Cost and Prerequisite repeat the Internal,
-- Concealed Ammo Drum's nearly word for word; its 15,000 is stored as
-- printed and the repeat is noted in its cost_note.
--
-- Every weapon figure was read off a 130 dpi render of p.163-168. The manifest lists substituted digits on p.164 (2) and p.165
-- (1), all in xlO-shaped dice that the render shows as x10.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('sovietski-forearm-shotgun-blaster', 'Blaster - Single- or Double-Barreled Shotgun', 'rifts', 'cybernetics', NULL, 14000, '14,000 credits. Explosive shells: light 100, medium 300, heavy 550, high 900 credits each.', '5D6 S.D.C. per solid slug; 3D6 S.D.C. per buckshot round (a 3 ft spread at 30 ft, 10 ft at 60 ft); light explosive shell 1D6x10 S.D.C.; medium, heavy and high explosive shells 1D6, 2D6 and 3D6 M.D.', 0, '120 feet (36.5 m)', 'Internal magazine of 20 rounds (Light Machine) or 40 (Heavy Machine), or a small or large external drum; hand-loads at one round per melee action', 'Each single shot or double blast is one melee attack', NULL, NULL, NULL, 'A forearm shotgun, one barrel or two, built for cyborgs who fight at close quarters in the cities or hunt demons and other supernatural foes. It takes any ordinary shotgun shell as well as anti-monster loads: buckshot laced with silver, or a slug plated in silver, and the twin-barrel model fires either barrel or both together. Silver, wood or stone rounds do M.D. to the creatures vulnerable to them. Fitted only to full conversion Light or Heavy Machines.', 'Rifts World Book 36: Sovietski p.163', NULL),
  ('sovietski-forearm-projectile-blaster', 'Blaster - Projectile Weapons (S.D.C. Forearm or Shoulder)', 'rifts', 'cybernetics', NULL, 15000, '15,000 credits as printed. The entry''s Penalties, Cost and Prerequisite lines repeat those of the Internal, Concealed Ammo Drum (p.166-167) nearly word for word, prerequisite included (a forearm blaster that fires projectiles).', 'Pistol: 6D6 S.D.C. single shot, 1D6x10 S.D.C. three-round burst (smaller heavy rounds 4D6 / 1D4x10). Submachine-gun: as the pistol, plus an eight-round burst of 2D4x10 S.D.C. (smaller rounds 1D6x10). Dart shooter: 1 S.D.C. plus the drug. Shotgun: 5D6 S.D.C. slug, 3D6 S.D.C. buckshot, or explosive rounds as the Cyber-Bow''s. Mini-machine-gun: 1 M.D. single shot, 2D4 M.D. per 10-round burst. Rubber riot rounds: 1 S.D.C.', 0, 'Pistol and submachine-gun 120 feet (36.5 m); dart shooter 100 feet (30.5 m); shotgun 120 feet (36.5 m); mini-machine-gun 2,000 feet (609 m)', 'Small drum on the hip or back: 400 pistol or submachine-gun rounds, 200 shotgun or dart rounds, or 300 mini-machine-gun rounds; most also take a standard magazine', 'Each burst is one melee attack; bursts are less accurate than an aimed single shot', NULL, NULL, NULL, 'A slug-thrower hidden in a bionic forearm, where it shows as a small barrel or a low bump on top of the arm, or carried as a shoulder gun that rises to fire. Meant for S.D.C. targets and for monsters hurt by silver, wood or stone ammunition. Five versions exist, matching a pistol, a submachine-gun, a dart shooter, a shotgun or a mini-machine-gun, each belt-fed from a small drum. Adds about 3-4 lbs (1.3-1.8 kg) to the arm. Penalties: -1 to strike with a shoulder mount; an arm with a slug-thrower holds at most one projectile and one energy weapon and gives up secret compartments and other forearm features, keeping only an ammo or E-Clip port and a hook-up for an external drum.', 'Rifts World Book 36: Sovietski p.163-164', NULL),
  ('sovietski-forearm-grenade-launcher', 'Blaster - Grenade Launcher (Forearm or Shoulder)', 'rifts', 'cybernetics', NULL, 45000, '45,000 credits in the forearm; 90,000 as a shoulder launcher. Poor availability. The lower figure is stored.', 'By grenade; the standard grenade does 5D6 M.D. to a 4 ft (1.2 m) radius', 1, '1,000 feet (305 m)', '2 grenades in the forearm or 4 in a shoulder launcher; reloads by hand at two per melee round (15 seconds)', 'One at a time', NULL, NULL, NULL, 'A built-in launcher, forearm or shoulder, that throws ordinary rifle grenades; any Sovietski rifle grenade will fit it.', 'Rifts World Book 36: Sovietski p.164', NULL),
  ('sovietski-bulletdusters', 'Bulletdusters', 'rifts', 'cybernetics', NULL, 20000, '20,000 credits for the first barrel with its ammo feed, 11,000 for each barrel after; the special rounds cost 75 credits each.', '+1D4 M.D. per barrel fired (one to three) on top of punch damage; optional S.D.C. rounds do 3D6 S.D.C./Hit Points per barrel', 1, 'Touch, or up to 90 feet (27.4 m) at -4 to strike', '8 rounds per barrel; cannot draw on an internal ammo drum', 'Fires whenever a punch or other blow lands; one barrel or all at once', NULL, NULL, NULL, 'Small barrels set between the knuckles, a scaled-down form of the Thunderfist Superheavy Machine''s implant, that fire an explosive round as a punch connects. A one-, two- or three-barrel version can go in each fist, fed from a forearm magazine, and the set counts as one forearm weapon. Shooting at range is wildly inaccurate. Penalties: -4 to strike at range, -10% on manual dexterity skills including Climbing; the barrels must be kept clean, and a fouled set does half its damage to the bionic hand each time it fires until switched off. Not for Cyber-Humanoids. Prerequisite: a full bionic hand and arm.', 'Rifts World Book 36: Sovietski p.164', NULL),
  ('sovietski-mega-damage-chainsaw', 'Chainsaw, Mega-Damage', 'rifts', 'cybernetics', NULL, 35000, '35,000 credits', '5D6 M.D. per slashing attack, or 5D6 M.D. per action held in a sustained attack', 1, 'Hand to hand only', NULL, NULL, NULL, NULL, NULL, 'The Sovietski answer to the chainsaw of the Orloff War Camp''s Aftermath Shocktroopers, its chain coated in artificial diamond M.D.C. material. It rides on top of the forearm in place of a blaster, or takes the place of hand and forearm altogether. Built to cut through body armor and bionic limbs, it also clears debris, fells timber, saws through M.D.C. barriers and serves in rescue and salvage. Awkward in a fight but well liked. It gives +1 on disarm and -1 on parry. Combat bonuses use W.P. Sword.', 'Rifts World Book 36: Sovietski p.164', NULL),
  ('sovietski-chemical-spray', 'Chemical Spray (Sovietski)', 'rifts', 'cybernetics', NULL, 40000, '40,000 credits for the spray system. Chemicals per dose: blinding agent 100-200, burning vapor 50, CO2 foam 100, tear gas 150-300, tranquilizer 100-200, smoke 75 credits; acid is not priced.', 'By chemical: burning vapor 1D6 S.D.C./Hit Points; industrial acid 4D6, 6D6, 1D4x10 or 1D6x10 S.D.C. or 1D4 M.D., burning on for 1D4 melee rounds unless washed off', 0, '20 feet (6.1 m)', '20 doses in all, of up to five chemicals; a dose of gas or CO2 foam uses two', 'Each spray is one melee attack', NULL, NULL, NULL, 'A spray system mounted in the legs or chest to vent a gas cloud around the cyborg (filling about 10 ft/3 m), or in the arm and hand, chest or mouth to aim a jet, usually liquid, at one target; liquid stores at twice the doses of gas. A directed spray covers 5 ft (1.5 m); a gas covers a 10 ft (3 m) circle and lingers for a melee round. Save: 16 or higher against nonlethal chemicals, 12 or higher against poisons and acid. Chemicals: blinding agent (3D4 melee rounds at -10 on strike/parry/dodge/disarm, speed -30%, no sight skills; goggles or a gas mask stop it); burning vapor (1D6 damage and -4 on strike/parry/dodge for 1D4 melees); CO2 foam for fires; tear gas (-10 on strike/parry/dodge/disarm, -3 initiative, speed -30%, one melee attack lost, for 1D6+1 melee rounds); tranquilizer (asleep within 1D4 melees for 2D4 minutes); smoke (gas only, a 10 ft cloud for 1D4+3 minutes that only thermo-imaging sees through). The acid is an industrial solvent, not meant as a weapon. Not the New West mining cyborg''s Chemical Spray tool, which is unpriced.', 'Rifts World Book 36: Sovietski p.164-165', NULL),
  ('sovietski-clawed-feet', 'Clawed Feet', 'rifts', 'cybernetics', NULL, 1000, '1,000 credits per S.D.C. claw or blade; 10,000 per M.D. Vibro-Blade claw. The lower figure is stored.', '4D6 S.D.C./Hit Points with S.D.C. claws, or 4D4 M.D. with Vibro-Blade claws', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Enlarged bionic feet ending in three or four clawed toes. Bonus: +5% to Climb.', 'Rifts World Book 36: Sovietski p.165', NULL),
  ('sovietski-crab-claw-vibro-blade-hands', 'Crab Claw Vibro-Blade Hands', 'rifts', 'cybernetics', NULL, 20000, '20,000 credits per hand, always on a modular housing', '1D6 M.D. per slash; 3D6 M.D. per scissoring clamp-cut', 1, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'Oversized scissor-like pincers with cutting edges along their tips and inner jaws, used to menace and maim an opponent. They cost the cyborg nearly all manual dexterity, his fingers and an opposable thumb, so they are discouraged, but they are often built as a modular unit that snaps on and off in place of a bionic hand as the job demands.', 'Rifts World Book 36: Sovietski p.165', NULL),
  ('sovietski-cyber-bow', 'Cyber-Bow and Arrows', 'rifts', 'cybernetics', NULL, NULL, 'The book prices the arrows, not the bow. Each arrow: simple S.D.C. 3, M.D.C. shaft 30, light explosive 100, medium explosive 300, heavy explosive 550, high explosive 900, tear gas 100, tranquilizer gas 250, paralysis gas 400, smoke 60, flare 10, neural disrupter 400, tracer bug 200, Vibro-Arrow 5,000 credits.', 'By arrow: simple 2D6+2 S.D.C.; M.D.C. shaft 4D6+4 S.D.C.; light explosive 1D6x10 S.D.C.; medium, heavy and high explosive 1D6, 2D6 and 3D6 M.D.; Vibro-Arrow 1D4 M.D.', 0, '700 feet (213 m)', 'One, loaded by hand; a quiver carries 15 more, or a Cyber-Quiver', '2-8 arrows per melee round by W.P. Archery and Targeting', NULL, NULL, NULL, 'A five-piece folding bow housed under the left arm or on the back, favored by Light Machines, partial conversions and special forces wanting a silent weapon for sniping and assassination. It springs out of its panel, snaps together in the hand with its string drawn tight, and stays tethered so it cannot be dropped or knocked away. Special arrows: gas arrows fill a 10 ft (3 m) area (save vs harmful drugs at 15; tranquilizer or paralysis lasts 1D6 minutes); smoke covers 20 ft (6 m) for 1D6+4 minutes in yellow, red, grey or black; a flare burns 60 seconds; the neural disrupter acts as a one-shot neural mace, reusable 1D6 times; the tracer bug transmits up to 8 miles (12 km) for 72 hours and may work loose (1-32% each half hour). Vibro-Arrows are bulky and wasteful and not sold openly, though Spetsnaz are rumored to have them made. Prerequisite: a full bionic arm.', 'Rifts World Book 36: Sovietski p.165', NULL),
  ('sovietski-cyber-quiver', 'Cyber-Quiver', 'rifts', 'cybernetics', NULL, 4000, '4,000 credits per quiver compartment', NULL, 0, NULL, '10 specialty arrows or 15 standard Cyber-Arrows', NULL, NULL, NULL, NULL, 'A closable arrow compartment set in a leg or the back to carry ammunition for the Cyber-Bow. Arrows sit in assigned slots, and the one called for lifts slightly to meet the hand. Many cyborgs keep specialty arrows in a leg quiver and ordinary ones in a back quiver.', 'Rifts World Book 36: Sovietski p.165', NULL),
  ('sovietski-e-clip-port', 'E-Clip Port', 'rifts', 'cybernetics', NULL, 3000, '3,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A standard E-Clip socket like those on energy weapons, fitted into the body to power a built-in weapon, back up a weapon''s supply, or run separate modules and non-weapon gear such as sensors and cameras.', 'Rifts World Book 36: Sovietski p.166', NULL),
  ('sovietski-extendible-legs', 'Extendible Hydraulic or Pneumatic Legs', 'rifts', 'cybernetics', NULL, 200000, '200,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Telescoping bionic legs that raise the cyborg to reach a high shelf or a ledge he can then pull himself onto, or to look over a wall. Typical leg P.S. 10-20. Speed is 30% below the usual maximum.', 'Rifts World Book 36: Sovietski p.166', NULL),
  ('sovietski-internal-concealed-ammo-drum', 'Internal, Concealed Ammo Drum Payload and Feed Mechanism', 'rifts', 'cybernetics', NULL, 15000, '15,000 credits', NULL, 0, NULL, '60 rounds for a pistol or submachine-gun equivalent; 20 for a sawed-off shotgun, dart shooter or mini-machine-gun; double in Heavy and Superheavy Machines. In addition to any external drum', 'As the weapon; each burst is one melee attack', NULL, NULL, NULL, 'An extra magazine for a forearm slug-thrower, shaped to sit under what looks like a swelling of armor on the underside of the bionic forearm, or inside an arm thicker than a human-proportioned limb. Penalties: an arm fitted with it holds one projectile and one energy weapon at most, and loses secret compartments, sensors and every other forearm feature except an ammo or E-Clip port and a hook-up for an external drum. Prerequisite: a forearm blaster that fires projectiles.', 'Rifts World Book 36: Sovietski p.166-167', NULL),
  ('sovietski-internal-divided-ammo-drum', 'Internal, Concealed, Divided Ammo Drum and Feed Mechanism', 'rifts', 'cybernetics', NULL, 25000, '25,000 credits', 'As the projectile weapon it feeds', 0, 'As the projectile weapon it feeds', 'Split evenly between two ammunition types, 10-30 rounds a side by ammo; double for Heavy Machines. In addition to any external drum or magazine', 'Each burst is one melee attack', NULL, NULL, NULL, 'The concealed forearm drum split into two halves with a dual feed, so the cyborg can change ammunition almost at once (one melee attack), say from ordinary rounds to silver or wood for a monster. Both loads must suit the same weapon: pistol and submachine-gun rounds mix, shotgun shells and darts or slugs and buckshot mix in a wide-bore blaster, and mini-machine-gun M.D. rounds mix with nothing. Penalties as the Internal, Concealed Ammo Drum. Prerequisite: a forearm blaster that fires projectiles.', 'Rifts World Book 36: Sovietski p.167', NULL),
  ('sovietski-large-external-ammo-drum', 'Large External Ammo Drum and Feed Mechanism', 'rifts', 'cybernetics', NULL, 45000, '45,000 credits; 68,000 for a divided drum holding two kinds of ammunition. The lower figure is stored.', NULL, 0, NULL, '900 rounds for a rail gun, mini-machine-gun, shotgun or dart weapon; 1,200 pistol or submachine-gun rounds; 90 grenades for a grenade launcher', NULL, NULL, NULL, 28, 'A big, plainly visible drum on the back that belt-feeds one or two built-in or carried projectile weapons, including hand-held rail guns, well beyond the small hip or back drum; Spetsnaz Dragunov Heavy Machines carry one for their rail guns and heavy rifles. Often worn alongside the small drum or a concealed forearm drum. One per cyborg. The drum has 28 M.D.C. Not for partial cyborgs, Headhunters or Cyber-Humanoids (it gives away a disguise). Penalties: Light Machines lose 20% Spd and take -10% to balance and to Acrobatics, Climbing, Gymnastics, Prowl and Swimming; Heavy and Superheavy Machines lose 5% Spd and take -5% to the same. Prerequisite: one integrated bionic weapon, or a hand-held rail gun, rifle or projectile weapon able to take an ammo belt.', 'Rifts World Book 36: Sovietski p.167', NULL),
  ('sovietski-legs-of-leaping', 'Legs of Leaping', 'rifts', 'cybernetics', NULL, 30000, '30,000 credits on top of the cost of the legs', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Bionic legs tuned for jumping and quick dodges: leaps of 15 ft (4.6 m) high and 30 ft (9.1 m) long, half again as far with leg booster jets. Bonus: +1 to dodge, and +1 initiative when dodging or leaping.', 'Rifts World Book 36: Sovietski p.167', NULL),
  ('sovietski-net-launcher', 'Net Launcher', 'rifts', 'cybernetics', NULL, NULL, 'The book prints no price for this entry, and none is stored.', 'None; entangles. A person needs 1D4 minutes to work free, a Light Machine 1D4 melee rounds, a Heavy or Superheavy Machine 1D4 melee actions', 0, '100 feet (30.5 m)', 'Forearm: one canister, usually with 1D4 spares carried; shoulder: three. Reloaded by hand, taking three melee actions', 'Single shots only', NULL, NULL, NULL, 'A wide-barreled launcher, on the forearm or in a shoulder turret, that looks like a mini-missile launcher. Compressed air (loud as it charges) throws a canister that bursts into an M.D.C. net big enough for a target twice human size and then tightens. Used by Sovietski Police and animal control, and in battle to take foes out for a time. The net has about 1 M.D.C. per square inch; claws, teeth, fire, M.D.C. blades and supernatural or cyborg strength can tear it, but cutting a way out takes at least two melee rounds (30 seconds).', 'Rifts World Book 36: Sovietski p.167-168', NULL),
  ('sovietski-quick-draw-holsters', 'Quick Draw Holsters (Triax Tech)', 'rifts', 'cybernetics', NULL, 14000, '14,000 credits each; a pair can sometimes be had for 22,000.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Holster compartments built into the legs, or into the torso''s sides on big Heavy Machines, holding handguns, knives or sawed-off shotguns, which leap into the cyborg''s hand at a mental command. Bonus: +1 initiative with a weapon drawn from one. Not the New West Quick Draw Holsters, which cost 10,000.', 'Rifts World Book 36: Sovietski p.168', NULL),
  ('sovietski-shoulder-turret', 'Shoulder Turret (Shoulder Weapon Turret, Shoulder Blaster)', 'rifts', 'cybernetics', NULL, 20000, '20,000 credits for the turret mounting, plus the forearm weapon fitted to it', 'As the forearm weapon fitted', 0, 'As the forearm weapon fitted', NULL, NULL, NULL, NULL, NULL, 'A compact turret on the shoulder or back that raises its weapon forward to fire over the shoulder. It takes any light or medium cyborg forearm system: blasters, a mini-machine-gun, a chemical spray, a flashlight, sensors or cameras. Arc of fire 180 degrees up and down and 180 side to side; it cannot fire behind. Projectile weapons usually draw on a Large External Ammo Drum on the back, one drum feeding a turret on each shoulder. Four systems (Grenade Launcher, Heavy Ion Blaster, Particle Beam, Laser Pulse Blaster) go on a shoulder only on the largest, heaviest cyborgs.', 'Rifts World Book 36: Sovietski p.168', NULL),
  ('sovietski-shoulder-turret-auto-attack', 'Shoulder Weapon Turret Auto-Attack Program', 'rifts', 'cybernetics', NULL, 200000, '200,000 credits', NULL, 0, 'By the optics, typically 1,200 feet (366 m)', NULL, 'Two attacks per melee', NULL, NULL, NULL, 'Links a shoulder turret to the cyborg''s combat computer and gives it its own optical sensor and Friend or Foe software, so it finds, tracks and fires on enemies the programmer has named. No bonuses. Because targets are named by broad type (a kind of D-Bee, Brodkil, demons, soldiers in a given insignia), it can open fire on envoys, allies, disguised agents, bystanders or harmless creatures. Prerequisite: a Light or Heavy Shoulder Turret, the Gromeko Friend or Foe Identification Computer, a Combat Computer and its ranged enhancement program.', 'Rifts World Book 36: Sovietski p.168', NULL),
  ('sovietski-tentacles', 'Tentacles (Additional Appendages)', 'rifts', 'cybernetics', NULL, 125000, '125,000 credits for one; 210,000 for a pair. The lower figure is stored.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 20, 'Mechanical tentacles fitted like extra arms, below the normal arms or on the shoulder blades, each ending in a small pair of claw fingers. Up to 5 ft (1.5 m) long, P.S. and P.P. 10 rising to at most 18; touch is only 25% and skills done with the claws are at -30%. Each tentacle has 20 M.D.C. and each claw 5. Bonuses: a pair, one extra attack per melee with +1 parry and +1 entangle; one alone, +1 parry.', 'Rifts World Book 36: Sovietski p.168', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 21 gear rows are in' AS assertion, count(*) AS got, 21 AS want
  FROM gear WHERE slug IN ('sovietski-forearm-shotgun-blaster', 'sovietski-forearm-projectile-blaster', 'sovietski-forearm-grenade-launcher', 'sovietski-bulletdusters', 'sovietski-mega-damage-chainsaw', 'sovietski-chemical-spray', 'sovietski-clawed-feet', 'sovietski-crab-claw-vibro-blade-hands', 'sovietski-cyber-bow', 'sovietski-cyber-quiver', 'sovietski-e-clip-port', 'sovietski-extendible-legs', 'sovietski-internal-concealed-ammo-drum', 'sovietski-internal-divided-ammo-drum', 'sovietski-large-external-ammo-drum', 'sovietski-legs-of-leaping', 'sovietski-net-launcher', 'sovietski-quick-draw-holsters', 'sovietski-shoulder-turret', 'sovietski-shoulder-turret-auto-attack', 'sovietski-tentacles') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~384-sovietski-bionic-weapons.sql');
